def solve(data):
    active = {}
    parents = []
    events = sorted(data['events'], key=lambda event: (event['minute'], event['seq']))
    for event in events:
        name = event['id']
        if event['kind'] == 'cancel':
            del active[name]
        else:
            parent = event['parent']
            parents.append(active.get(parent))
            active[name] = len(parents) - 1

    active_versions = set(active.values())
    supported = set()
    for version, parent in enumerate(parents):
        if version in active_versions and (parent is None or parent in supported):
            supported.add(version)
    return sorted(name for name, version in active.items() if version not in supported)

